import { Suspense } from 'react'
import { RevenueChart, RevenueChartSkeleton } from './RevenueChart'
import { LatestInvoices, LatestInvoicesSkeleton } from './LatestInvoices'
import { CardStats, CardStatsSkeleton } from './CardStats'

// Not async: nothing is awaited here, so <main>, the heading, and every fallback
// are prerendered into the static shell. Each section fetches inside its own
// boundary and streams in at request time.
export default function Page() {
  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<CardStatsSkeleton />}>
        <CardStats />
      </Suspense>
      <Suspense fallback={<RevenueChartSkeleton />}>
        <RevenueChart />
      </Suspense>
      <Suspense fallback={<LatestInvoicesSkeleton />}>
        <LatestInvoices />
      </Suspense>
    </main>
  )
}

